package dev.veltraph.client.core;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FreshLifecycleDataReuseTest {
 @Test void freshSnapshotIdentityNeverCollapses(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);var first=root.lifecycleSnapshot();var second=root.lifecycleSnapshot();assertNotSame(first,second);assertTrue(root.lifecycleCurrent(first));assertTrue(root.lifecycleCurrent(second));assertSame(actor.storedLifecycle(),actor.storedLifecycle());}
 @Test void actualStoredStateIsReadOnEveryHotCall(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);var first=actor.storedLifecycle();var old=root.lifecycleSnapshot();actor.pause();var next=actor.storedLifecycle();assertNotSame(first,next);assertFalse(first.same(next));assertFalse(root.lifecycleCurrent(old));assertTrue(root.lifecycleCurrent(root.lifecycleSnapshot()));}
 @Test void realEnableABANeverReusesOldStampOrReceipt(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);var first=actor.storedLifecycle();var old=root.lifecycleSnapshot();actor.setEnabled(false);actor.setEnabled(true);assertNotSame(first,actor.storedLifecycle());assertFalse(root.lifecycleCurrent(old));}
 @Test void registrationAndInputBindingAreFreshWrapperData(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);var old=root.lifecycleSnapshot();root.leasedInputOwner(()->actor);assertFalse(root.lifecycleCurrent(old));var bound=root.lifecycleSnapshot();root.register(new Actor("other"));assertFalse(root.lifecycleCurrent(bound));}
 @Test void privateParentChildFinishingWitnessKeepsOriginalTransitionSemantics(){var parent=new Actor("parent");var child=new Actor("child");parent.setEnabled(true);child.setEnabled(true);var witness=CombatFinishingLifecycle.capture(parent,child);assertNotNull(witness);assertTrue(witness.current());child.setEnabled(false);assertTrue(witness.childStoppedNormally());assertFalse(witness.current());child.setEnabled(true);assertFalse(witness.childStoppedNormally());}
 @Test void hotReadsInvokeNoRoleCallback(){var root=new ModuleManager();var actor=new Actor("parent");root.register(actor);actor.setEnabled(true);for(int i=0;i<20;i++){assertTrue(root.lifecycleCurrent(root.lifecycleSnapshot()));assertEquals(0,actor.roles);}}
 private static final class Actor extends AbstractModule {int roles;Actor(String id){super(id,id,ModuleCategory.INTERMEDIARY);}void pause(){setState(MacroState.PAUSED);}@Override public boolean ownsGameplayInput(){roles++;throw new AssertionError("no role calls in private snapshot");}}
}
